_file_map = {

    "clients.baml": "// =============================================================================\n// Polyglot Agentic Data Mesh — BAML Client Definitions\n// =============================================================================\n\n// --- OpenRouter (Cloud-native Qwen/Thinker) ---\nclient<llm> OpenRouter {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    model \"google/gemini-3-flash-preview\" // Updated per user request\n  }\n}\n\n// --- Ollama (Local LLM Deployment) ---\nclient<llm> Ollama {\n  provider openai\n  options {\n    base_url env.OLLAMA_BASE_URL // Configurable via environment variable\n    api_key \"ollama\"\n    model \"gpt-oss-120b\" // Updated to GPT-OSS-120B\n  }\n}\n\n// --- OpenAI (Native Fallback) ---\nclient<llm> OpenAI {\n  provider openai\n  options {\n    model \"gpt-4o\"\n    api_key env.OPENAI_API_KEY\n  }\n}\n\n// --- Main Mesh Brain ---\n// This acts as the single point of configuration for all agents.\n// Switch the fallback order or primary client here.\nclient<llm> MainAgent {\n  provider fallback\n  options {\n    strategy [OpenRouter, OpenAI] // Primary OpenRouter, fallback to OpenAI\n  }\n}\n",
    "contracts.baml": "// =============================================================================\n// Polyglot Agentic Data Mesh - Shared Data Contracts\n// =============================================================================\n// These BAML definitions serve as the single source of truth for ALL agent\n// communication across the mesh. Every microservice (Engine A: Restate+Smolagents,\n// Engine B: LangGraph) must serialize/deserialize to these schemas.\n//\n// IMPORTANT: Ontology classes are NOT hardcoded here. They are dynamically\n// injected at runtime from the RDF graph via the active_ontology_classes\n// parameter in ClassifySustainmentIntent.\n// =============================================================================\n\n// -----------------------------------------------------------------------------\n// Enums\n// -----------------------------------------------------------------------------\n\n/// Status returned by any agent after processing a task.\nenum AgentStatus {\n  SUCCESS\n    @description(\"The agent completed the task without errors.\")\n  FAILED\n    @description(\"The agent encountered an unrecoverable error.\")\n  HUMAN_REQUIRED\n    @description(\"The agent needs human-in-the-loop intervention to proceed.\")\n}\n\n// -----------------------------------------------------------------------------\n// Semantic Resolution\n// -----------------------------------------------------------------------------\n\n/// Result of mapping free-text input to a canonical sustainment concept.\n/// The resolved_uri is a dynamic ontology URI (not a hardcoded enum) that\n/// comes from the RDF graph at runtime.\nclass SemanticResolution {\n  resolved_uri string\n    @description(\"The ontology URI that best matches the input query. Must be one of the URIs provided in active_ontology_classes.\")\n  confidence_score float\n    @description(\"Model confidence in the match, between 0.0 and 1.0.\")\n  suggested_dbt_models string[]\n    @description(\"Ordered list of dbt model names relevant to the resolved concept.\")\n}\n\n// -----------------------------------------------------------------------------\n// Agent Input\n// -----------------------------------------------------------------------------\n\n/// The universal task payload sent from the Dagster orchestrator to any agent\n/// pod via HTTP POST. Every agent endpoint must accept this schema.\nclass AgentTask {\n  task_description string\n    @description(\"Human-readable description of the work the agent should perform.\")\n  dataset_id string\n    @description(\"Identifier for the target dataset or data asset in the mesh.\")\n  semantic_context SemanticResolution?\n    @description(\"Optional pre-resolved semantic context. When present, agents can skip their own classification step.\")\n}\n\n// -----------------------------------------------------------------------------\n// Agent Output\n// -----------------------------------------------------------------------------\n\n/// The universal response payload returned by every agent pod.\n/// The Dagster orchestrator inspects this to decide on next steps\n/// (e.g., retry, escalate, or continue the pipeline).\nclass AgentResponse {\n  status AgentStatus\n    @description(\"Outcome of the agent's execution.\")\n  summary string\n    @description(\"Brief human-readable summary of what the agent did.\")\n  extracted_metrics map<string, float>\n    @description(\"Key-value pairs of domain metrics extracted during processing.\")\n}\n\n// -----------------------------------------------------------------------------\n// BAML Function — Semantic Intent Classification\n// -----------------------------------------------------------------------------\n\n/// Classifies a user query against dynamically-provided ontology classes.\n/// The active_ontology_classes string is injected at runtime from the RDF\n/// graph — it contains a newline-delimited list of valid ontology URIs.\nfunction ClassifySustainmentIntent(query: string, active_ontology_classes: string) -> SemanticResolution {\n  client MainAgent\n  prompt #\"\n    You are a sustainment-domain semantic classifier.\n    \n    Your job is to map the user's query to exactly ONE ontology URI from the\n    list below. Do NOT invent URIs — you must select strictly from this list.\n\n    --- ACTIVE ONTOLOGY CLASSES ---\n    {{ active_ontology_classes }}\n    --- END ---\n\n    User query: {{ query }}\n\n    Instructions:\n    1. Analyze the user's query for sustainment-domain intent.\n    2. Select the single best-matching ontology URI from the list above.\n    3. Assign a confidence score between 0.0 and 1.0.\n    4. Suggest an ordered list of dbt model names that would be relevant\n       to the matched concept.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Engine E (Neo4j Graph Expert) Data Contracts\n// =============================================================================\n\n/// Target persona for the graph expert response\nenum PersonaTarget {\n  @@dynamic\n}\n\nclass MechanicResponse {\n  tool_list string[]\n  safety_warnings string[]\n  short_answer string\n}\n\nclass AuthoringResponse {\n  draft_content string @description(\"A clear, formatted Markdown summary of the requested technical data. Do NOT use XML.\")\n  missing_info_flags string[] @description(\"List of any required technical data that was missing from the graph.\")\n}\n\nclass LogisticsResponse {\n  impacted_platforms string[]\n  blocked_procedures string[]\n  risk_severity string\n}\n\nclass AuditResponse {\n  non_compliant_nodes string[]\n  rule_violated string\n  recommended_fix string\n}\n\nclass DataStewardResponse {\n  tool_list string[]\n  safety_warnings string[]\n  short_answer string\n}\n\nclass GraphExpertResponse {\n  confidence_score float\n  referenced_uris string[]\n  data MechanicResponse | AuthoringResponse | LogisticsResponse | AuditResponse | DataStewardResponse\n}\n\nfunction FormatGraphResponse(raw_text: string, persona: string) -> GraphExpertResponse {\n  client MainAgent\n  prompt #\"\n    You are a technical data formatting expert.\n    Turn the following raw data extracted from a Neo4j military graph database\n    into a structured response tailored for a {{ persona }}.\n\n    Raw Grapy Query Results:\n    {{ raw_text }}\n\n    CRITICAL GROUNDING RULES:\n    1. STRICT ADHERENCE: You are in a strict military context. DO NOT invent or hallucinate data, procedures, or hazards.\n    2. NO GENERIC ADVICE: Do not invent generic safety advice unless those exact words are in the raw data.\n    3. NULL STATE TRIGGER: If the input raw data is empty or missing, you MUST return NULL_GRAPH_RESPONSE as the primary content of your response (e.g. in short_answer or equivalent).\n    4. NO PANIC: Do not invent \"red-flagged\" areas or \"unscheduled maintenance\" if the query results are simply empty.\n    5. STRICT MARKDOWN FORMATTING: You are writing for a React Markdown renderer. You MUST use strict Markdown hierarchy (e.g., ### Section Name). You MUST place a double newline (\\n\\n) before and after EVERY header, list, and paragraph. If you fail to use double newlines, the text will crush together into an unreadable block.\n    6. EMBEDDING FIGURES: If the raw graph data contains Figure URLs and Titles, you MUST embed them directly into your short_answer or draft_content using standard Markdown image syntax: ![Image Title](Image URL). Place the image on a new line immediately following the step that references it.\n\n    Instructions:\n    1. Parse the raw text carefully.\n    2. Format it into the specific response structure required for a {{ persona }}.\n    3. Include a confidence score and a list of any referenced URIs.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Phase 2: Dynamic Supervisor Planning Contracts\n// =============================================================================\n\nclass AgentTaskDefinition {\n  target_persona PersonaTarget\n  sub_query string\n}\n\nclass SupervisorTaskPlan {\n  tasks AgentTaskDefinition[]\n  extracted_concepts string[] @description(\"List of main entities/components the user is asking about (e.g., 'Auxiliary Fuel Pump', 'C-130'). This populates the Ontology Map.\")\n  reasoning string\n}\n\nfunction DecomposeQuery(raw_query: string, active_personas: string) -> SupervisorTaskPlan {\n  client MainAgent\n  prompt #\"\n    Break this complex user query into discrete tasks.\n\n    User Query:\n    {{ raw_query }}\n\n    Instructions:\n    1. Extract the core entities, components, or systems the user is asking about and list them in `extracted_concepts`.\n    2. Assign each task to the correct specialized persona chosen STRICTLY from the Active Agent Roster below.\n    3. Read the specific rules and domain constraints for each persona in the roster. Do not misassign tasks.\n    4. If the query only needs one persona, return a list with just one task.\n    5. Provide your reasoning for why the query was split this way.\n\n    --- ACTIVE AGENT ROSTER ---\n    {{ active_personas }}\n    --- END ROSTER ---\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Phase 3: Mesh Intent Routing (Multi-Domain)\n// =============================================================================\n\nenum Intent {\n  @@dynamic\n}\n\nenum Domain {\n  @@dynamic\n}\n\nclass MeshRoutingDecision {\n  intent Intent\n  domain Domain\n  confidence float @description(\"Confidence in both intent and domain classification.\")\n  reasoning string @description(\"Why you routed it this way.\")\n  task_plan SupervisorTaskPlan? @description(\"Populate for all operational intents (queries, creation, retrieval, audits) to seed the multi-agent execution.\")\n}\n\nfunction RouteAndPlan(user_query: string) -> MeshRoutingDecision {\n  client MainAgent\n  prompt #\"\n    Act as the Kernel Scheduler for a Multi-Domain Agentic Mesh.\n    Analyze the user's query and determine the execution intent and domain.\n    \n    CRITICAL INSTRUCTIONS: \n    1. You must select the intent, domain, and personas strictly from the permitted values defined in the output format below.\n    2. DO NOT populate a task plan if the intent is SYSTEM_META_AND_REJECTION.\n    \n    User Query:\n    {{ user_query }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Engine W (Weaviate Semantic Expert) Data Contracts\n// =============================================================================\n\nclass KnowledgeResponse {\n  summary string @description(\"A clear, professional summary answering the user's knowledge or policy question. Format in Markdown.\")\n  referenced_documents string[] @description(\"List of manual sections, policies, or documents cited in the summary.\")\n  confidence_score float\n}\n\nfunction FormatKnowledgeResponse(raw_text: string, domain: string) -> KnowledgeResponse {\n  client MainAgent\n  prompt #\"\n    You are a Technical Editor. \n    Format the following raw text generated by our Semantic Agent into a clean, readable summary for the {{ domain }} domain.\n    \n    Raw Agent Output:\n    {{ raw_text }}\n    \n    CRITICAL RULES:\n    1. Do not invent information. If the agent says the information was not found, state that clearly in the summary.\n    2. Extract any document references or policy names mentioned in the text into the referenced_documents array.\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Recipe 1 (Path A): Stateless Dagster Synthesis\n// =============================================================================\n\nclass FinalSynthesis {\n  markdown_report string\n}\n\nfunction SynthesizeReports(original_query: string, raw_json_results: string) -> FinalSynthesis {\n  client MainAgent\n  prompt #\"\n    You are a Principal Technical Writer. Your job is to synthesize an array of JSON results \n    from our specialized Graph Expert agents into a single, cohesive, highly readable Markdown report.\n\n    Original User Query:\n    {{ original_query }}\n\n    Raw JSON Results from Agents:\n    {{ raw_json_results }}\n\n    Instructions:\n    1. Organize the findings logically based on the user's original query.\n    2. Format the output with clear headers, bullet points, and emphasis where needed.\n    3. Ensure the final report is beautiful, highly readable, and professional.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// =============================================================================\n// Engine F (Presentation Agent) UI Routing Contracts\n// =============================================================================\n\n/// The visual tone or mood to pass to the frontend\nenum MoodType {\n  ROUTINE\n  URGENT\n  SUCCESS\n  STRATEGIC\n  EDUCATIONAL\n}\n\nenum SemanticArchetype {\n  PROCESS_TOPOLOGY     // Maps to workflows, steps, BPMN\n  HAZARD_DECLARATION   // Maps to safety, risk, warnings\n  ASSET_STATE_METRIC   // Maps to inventory, telemetry, tables\n  KNOWLEDGE_DOCUMENT   // Maps to manuals, standard text, code\n}\n\nenum SeverityLevel {\n  INFO\n  WARNING\n  CRITICAL\n}\n\n// 1. Base building blocks\nclass UIEntity {\n  id string\n  name string?\n  type string?\n  description string?\n}\n\nclass UIRelation {\n  source string\n  target string\n  relation string?\n  predicate string?\n}\n\n// 2. Strict UI Component Schemas\nclass TopologyUI {\n  archetype SemanticArchetype @description(\"MUST be PROCESS_TOPOLOGY\")\n  source_persona string? @description(\"The persona that produced this data (e.g. MECHANIC, PROCESS_ENGINEER). Copy from the raw data 'persona' field.\")\n  subject_concept string?\n  nodes UIEntity[]\n  edges UIRelation[]\n}\n\nclass HazardUI {\n  archetype SemanticArchetype @description(\"MUST be HAZARD_DECLARATION\")\n  source_persona string? @description(\"The persona that produced this data. Copy from the raw data 'persona' field.\")\n  subject_concept string?\n  severity SeverityLevel\n  hazards UIEntity[]\n}\n\nclass MetricUI {\n  archetype SemanticArchetype @description(\"MUST be ASSET_STATE_METRIC\")\n  source_persona string? @description(\"The persona that produced this data. Copy from the raw data 'persona' field.\")\n  subject_concept string?\n  metrics UIEntity[]\n}\n\nclass DocumentUI {\n  archetype SemanticArchetype @description(\"MUST be KNOWLEDGE_DOCUMENT\")\n  source_persona string? @description(\"The persona that produced this data. Copy from the raw data 'persona' field.\")\n  subject_concept string?\n  markdown_content string\n}\n\n// 3. Composite Dashboard Container\nclass DashboardUI {\n  components (TopologyUI | HazardUI | MetricUI | DocumentUI)[]\n}\n\n// 4. Update the router function to return the Composite Dashboard\nfunction DesignUI(raw_data: string, persona: string) -> DashboardUI {\n  client MainAgent\n  prompt #\"\n    Act as a Semantic UI Translator. Do NOT output frontend code. \n    Analyze the raw data array (which contains outputs from multiple expert agents) and the Target Persona.\n    \n    CRITICAL INSTRUCTION:\n    You are building a Composite Dashboard. You must output a `DashboardUI` object containing an array of components.\n    Create a separate UI component in the `components` array for EACH distinct expert response in the raw data.\n    ALWAYS copy the `persona` field from each raw data entry into the `source_persona` field of the corresponding component.\n    \n    CRITICAL GROUNDING RULES:\n    1. STRICT ADHERENCE: You are in a strict military context. DO NOT invent or hallucinate data, procedures, or hazards.\n    2. NO GENERIC ADVICE: Do not invent generic safety advice unless those exact words are in the raw data.\n    3. NULL STATE TRIGGER: If the data is empty or missing, trigger the Null State.\n    4. NULL STATE FORMAT: To trigger Null State, output a single DocumentUI in the components array. Set archetype to KNOWLEDGE_DOCUMENT and markdown_content to exactly: # SYSTEM ALERT\\nNo relevant records found. Do not proceed without manual verification.\n    \n    EXAMPLES:\n    - If the raw data has a Process Engineer's steps AND a Mechanic's safety warnings: \n      Output an array with 1 TopologyUI object AND 1 HazardUI object.\n    - If the raw data has a Tech Writer's text: Output a single DocumentUI object.\n    - PROCESS_ENGINEER: use TopologyUI. Map steps to nodes and connections to edges.\n    - Safety warning: use HazardUI. Map hazards to the hazards array.\n    - Manual/Text: use DocumentUI. Map text to markdown_content.\n    \n    --- RAW DATA ---\n    {{ raw_data }}\n    \n    --- TARGET PERSONA ---\n    {{ persona }}\n    \n    INSTRUCTIONS FOR DATA STEWARD / TABLES:\n    - If the raw data contains a list of database tables, dbt models, or sensor schemas: \n      USE MetricUI (ASSET_STATE_METRIC). Map each table name to a UIEntity in the `metrics` array.\n    - If the raw data is from a DATA_STEWARD: prioritize MetricUI for schema/table lists.\n    \n    {{ ctx.output_format }}\n  \"#\n}\n",
    "generators.baml": "// Generator configuration for the shared BAML contracts.\n// Outputs type-safe Python client code to baml_shared/baml_client/.\n\ngenerator target {\n  output_type \"python/pydantic\"\n  output_dir \"../baml_client\"\n  version \"0.219.0\"\n}\n",
    "interview_contracts.baml": "// The Cortex — Stateful BPMN Socratic Interview Contract\n// The LLM iteratively builds a BPMN graph on each chat turn.\n// ServiceTasks are semantically grounded to ontology classes + data sources.\n\n// ── BPMN Node Types ─────────────────────────────────────\n\nenum BPMNNodeType {\n  ServiceTask     @description(\"An automated task executed by an agent. MUST have ontology_class and data_source.\")\n  UserTask        @description(\"A manual step requiring human input or review.\")\n  ExclusiveGateway @description(\"A branching point — exactly one outgoing path is taken based on a condition.\")\n  TimerEvent      @description(\"A time-based trigger or delay (e.g. cron schedule, wait interval).\")\n}\n\n// ── BPMN Graph Elements ─────────────────────────────────\n\nclass BPMNNode {\n  id string @description(\"Unique identifier for this node, e.g. 'task_1', 'gw_1', 'timer_1'.\")\n  name string @description(\"Human-readable label for this node, e.g. 'Ingest Engine Telemetry'.\")\n  node_type BPMNNodeType @description(\"The BPMN element type.\")\n  ontology_class string? @description(\"IOF-MRO / MIMOSA ontology URI grounding this node. REQUIRED for ServiceTask, null for others. Must come from the available_ontology_classes list.\")\n  data_source string? @description(\"DataHub / dbt model name grounding this node. REQUIRED for ServiceTask, null for others. Must come from the available_data_sources list.\")\n}\n\nclass BPMNEdge {\n  source_id string @description(\"The id of the source BPMNNode.\")\n  target_id string @description(\"The id of the target BPMNNode.\")\n  condition_expression string? @description(\"For edges leaving an ExclusiveGateway, the boolean condition that activates this path. Null for unconditional flows.\")\n}\n\n// ── Interview State (returned each turn) ────────────────\n\nclass BPMNInterviewState {\n  nodes BPMNNode[] @description(\"The full list of BPMN nodes in the current graph. Updated cumulatively on each turn.\")\n  edges BPMNEdge[] @description(\"The full list of edges connecting nodes. Updated cumulatively on each turn.\")\n  unresolved_paths string[] @description(\"Human-readable descriptions of dead-end paths, missing connections, or ambiguities that need user input to resolve. E.g. 'Gateway gw_1 has no outgoing edge for the FALSE branch.'\")\n  is_ready_to_compile bool @description(\"True ONLY when: (1) there are zero unresolved_paths, (2) every ServiceTask has ontology_class and data_source filled, (3) the user has explicitly confirmed the workflow is complete. Default to false.\")\n  agent_reply string @description(\"Natural language response to the user. This is the conversational text shown in the Neural Stream.\")\n}\n\n// ── Main Function ───────────────────────────────────────\n\nfunction IterateBPMNGraph(\n  chat_history: string,\n  user_message: string,\n  current_graph_json: string,\n  available_ontology_classes: string,\n  available_data_sources: string,\n) -> BPMNInterviewState {\n  client MainAgent\n  prompt #\"\n    {{ _.role(\"system\") }}\n    You are the Socratic Process Architect — an expert AI interviewer operating\n    within The Cortex, an industrial data mesh interrogation system.\n\n    YOUR MISSION: Iteratively build a BPMN workflow graph through conversation.\n    On every turn you receive the current graph state and the user's message.\n    You must return the COMPLETE updated graph (all nodes + edges), not just deltas.\n\n    ══════════════════════════════════════════════════════════\n    AVAILABLE ONTOLOGY CLASSES (from live IOF-MRO / MIMOSA service):\n    {{ available_ontology_classes }}\n\n    AVAILABLE DATA SOURCES (from live DataHub / dbt catalog):\n    {{ available_data_sources }}\n    ══════════════════════════════════════════════════════════\n\n    CURRENT GRAPH STATE:\n    {{ current_graph_json }}\n\n    ══════════════════════════════════════════════════════════\n    STRICT RULES — FOLLOW THESE EXACTLY:\n\n    1. ITERATIVE BUILDING: Add, modify, or remove nodes and edges based on the\n       user's latest message. Always return the FULL graph, not just changes.\n\n    2. SEMANTIC GROUNDING (MANDATORY): Every time you create or keep a ServiceTask,\n       you MUST fill BOTH ontology_class and data_source from the lists above.\n       — ontology_class must be an EXACT match from AVAILABLE ONTOLOGY CLASSES.\n       — data_source must be an EXACT match from AVAILABLE DATA SOURCES.\n       — If no match exists, tell the user and suggest the closest option.\n       — UserTask, ExclusiveGateway, and TimerEvent do NOT need these fields.\n\n    3. DEAD-END TRACKING: After every update, scan the graph for:\n       — Nodes with no outgoing edges (unless they are terminal nodes)\n       — ExclusiveGateways with fewer than 2 outgoing edges\n       — Missing condition_expression on gateway edges\n       — ServiceTasks with null ontology_class or data_source\n       List all issues in unresolved_paths with clear descriptions.\n\n    4. COMPILATION GATE: You may ONLY set is_ready_to_compile = true when:\n       — unresolved_paths is EMPTY\n       — Every ServiceTask has ontology_class AND data_source filled\n       — The graph has at least one start node and one end node\n       — The user has EXPLICITLY confirmed the workflow is complete\n       If ANY of these conditions is not met, is_ready_to_compile MUST be false.\n\n    5. SOCRATIC QUESTIONING: Ask focused follow-up questions to resolve\n       ambiguities. Guide the user to define:\n       — What triggers the workflow (TimerEvent or manual start)\n       — What data transformations are needed (ServiceTasks)\n       — Where branching logic applies (ExclusiveGateways)\n       — What human review steps are needed (UserTasks)\n\n    BEHAVIOR:\n    - Keep agent_reply concise (2-5 sentences). Be technical but approachable.\n    - When you add a new node, briefly explain what it does and why.\n    - When reporting unresolved_paths, phrase them as questions to the user.\n    - Use IDs like task_1, task_2, gw_1, timer_1 — incrementing per type.\n\n    {{ _.role(\"user\") }}\n    CONVERSATION SO FAR:\n    {{ chat_history }}\n\n    LATEST MESSAGE:\n    {{ user_message }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
}

